package com.hireflow.storage;

/**
 * Where uploaded files live (docs/architecture.md §10). Two kinds, stored differently:
 *
 * <ul>
 *   <li><b>Public images</b> (logos, profile pictures): anyone with the URL may view them. The URL is
 *       saved in the database.</li>
 *   <li><b>Private files</b> (resumes): never reachable directly. Callers check permissions, then ask
 *       {@link #openPrivateFile} for a short-lived way in. Only the key is saved.</li>
 * </ul>
 *
 * Keys are generated by callers (e.g. {@code resumes/<uuid>.pdf}), never taken from user input.
 * Implementations: {@link LocalFileStorage} (development, tests) and {@link CloudinaryFileStorage}.
 */
public interface FileStorage {

    /** Stores or replaces an image and returns its public URL (versioned, so browsers don't show a stale copy). */
    String storePublicImage(String key, byte[] bytes, FileType type);

    void deletePublicImage(String key);

    /** Stores a private file. Fails if the key already exists. */
    void storePrivateFile(String key, byte[] bytes, FileType type);

    /** A short-lived way to read a private file, for a caller that has already checked permissions. */
    PrivateFileAccess openPrivateFile(String key, String downloadName);

    void deletePrivateFile(String key);
}
